CREATE COLUMN TABLE "TEST_AP"."PMV8" ("DocNum" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "InvType" NVARCHAR(20), "DocEntry" INTEGER CS_INT, "DocLine" INTEGER CS_INT, "ObjectType" NVARCHAR(20) DEFAULT '24', "LogInstanc" INTEGER CS_INT DEFAULT 0, "PaidEntry" INTEGER CS_INT, "PaidLine" INTEGER CS_INT, PRIMARY KEY ("DocNum", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."PMV8" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$InvType$DocEntry$DocLine$','InvType','DocEntry','DocLine'));
ALTER TABLE "TEST_AP"."PMV8" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$PaidEntry$PaidLine$','PaidEntry','PaidLine'));
CREATE INDEX "PMV8_INVOICE" ON "TEST_AP"."PMV8" ( "InvType" ASC, "DocEntry" ASC, "DocLine" ASC );
CREATE INDEX "PMV8_PAYMENT" ON "TEST_AP"."PMV8" ( "PaidEntry" ASC, "PaidLine" ASC )